(() => {
  'use strict';
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const $ = (id) => document.getElementById(id);
  const menu = $('menu'), intro = $('intro'), gameUI = $('game-ui'), endScreen = $('end-screen');
  let W = 0, H = 0, dpr = 1, last = 0, scene = 'menu', muted = true, audio;
  const WORLD = 3620;
  const keys = Object.create(null), touch = Object.create(null);
  const player = { x: 120, y: 0, vx: 0, vy: 0, w: 30, h: 58, health: 100, grounded: false, facing: 1, invuln: 0, pulse: 0, attackCooldown: 0, interact: false, sample: false, opened: false };
  let camera = 0, time = 0, introStart = 0, toastTimer = 0, subtitleTimer = 0, pulseFlash = 0, visited = {}, worldItems = [], enemies = [], particles = [];
  const floorRatio = .79;
  const roomData = [
    { x: 0, end: 800, name: 'HANGAR 04', color: '#49666d' },
    { x: 800, end: 1640, name: 'ALOJAMIENTO', color: '#597075' },
    { x: 1640, end: 2480, name: 'LABORATORIO', color: '#765f63' },
    { x: 2480, end: 3260, name: 'NÚCLEO', color: '#827163' },
    { x: 3260, end: WORLD, name: 'CÁMARA DE ESCAPE', color: '#54737a' }
  ];
  const storyHTML = `<span class="chapter">BITÁCORA DE LA COMANDANTE VEGA &nbsp; / &nbsp; 2189.11.06</span><br><br>El carguero <i>Orfeo</i> respondió a una señal bajo el hielo de Ío. Su cápsula de recuperación llegó sellada. <span class="dim">No registró signos de vida.</span><br><br>La doctora Sato encontró algo latiendo dentro del hielo. Lo llamaron <span class="emph">organismo X-17</span>. En menos de seis horas, la muestra se abrió paso a través del contenedor.<br><br>Primero cayó el equipo de xenobiología. Después, los dormitorios. <span class="dim">No estaban muertos. Algo aprendía a usar sus cuerpos.</span><br><br>La infección se transmite por contacto y por el aire. La estación inició el protocolo de cuarentena, pero alguien anuló los cierres desde el núcleo.<br><br><span class="emph">La señal de auxilio que recibiste es una trampa.</span><br><br>Tu cápsula ya no tiene combustible. Recupera el registro del laboratorio, reactiva el núcleo y llega al hangar de evacuación.<br><br><span class="chapter">SI ALGUIEN ENCUENTRA ESTA GRABACIÓN: NO RESPONDAN A LAS VOCES.</span>`;
  $('story-text').innerHTML = storyHTML;
  function resize() { const rect = canvas.getBoundingClientRect(); W = Math.max(1, rect.width); H = Math.max(1, rect.height); dpr = Math.min(2, window.devicePixelRatio || 1); canvas.width = Math.round(W * dpr); canvas.height = Math.round(H * dpr); ctx.setTransform(dpr, 0, 0, dpr, 0, 0); }
  window.addEventListener('resize', resize); resize();
  function show(el) { el.classList.add('visible'); }
  function hide(el) { el.classList.remove('visible'); }
  function playSound(freq=180, duration=.08, type='sine', volume=.035) {
    if (muted) return;
    try { audio ||= new (window.AudioContext || window.webkitAudioContext)(); const o=audio.createOscillator(), g=audio.createGain(); o.type=type; o.frequency.setValueAtTime(freq,audio.currentTime); o.frequency.exponentialRampToValueAtTime(Math.max(35,freq*.55),audio.currentTime+duration); g.gain.setValueAtTime(volume,audio.currentTime); g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration); o.connect(g); g.connect(audio.destination); o.start(); o.stop(audio.currentTime+duration); } catch (_) {}
  }
  function toast(text, duration=3.1) { const el=$('toast'); el.textContent=text; el.classList.add('show'); toastTimer=duration; }
  function subtitle(text, duration=3.8) { const el=$('subtitle'); el.textContent=text; el.classList.add('show'); subtitleTimer=duration; }
  function freshGame() {
    Object.assign(player,{x:120,y:0,vx:0,vy:0,health:100,grounded:false,facing:1,invuln:0,pulse:0,attackCooldown:0,interact:false,sample:false,opened:false});
    camera=0; time=0; visited={}; particles=[];
    worldItems=[{x:1460,type:'terminal',active:true,label:'REGISTRO X-17'},{x:2350,type:'reactor',active:true,label:'REACTIVAR NÚCLEO'},{x:3440,type:'exit',active:true,label:'EVACUAR'},{x:680,type:'med',active:true},{x:1980,type:'med',active:true}];
    enemies=[{x:590,dir:-1,hp:1,phase:0},{x:1210,dir:1,hp:1,phase:1},{x:1840,dir:-1,hp:1,phase:2},{x:2860,dir:1,hp:1,phase:3},{x:3150,dir:-1,hp:1,phase:4}];
    updateHud();
  }
  function beginIntro() { freshGame(); scene='intro'; hide(menu); show(intro); gameUI.classList.remove('visible'); introStart=performance.now(); $('story-text').style.top='100%'; $('story-text').style.transition='none'; requestAnimationFrame(()=>{ $('story-text').style.transition='top 23s linear'; $('story-text').style.top='-160%'; }); playSound(95,.5,'sine',.055); }
  function beginPlay() { if (scene==='playing') return; scene='playing'; hide(intro); hide(menu); hide(endScreen); gameUI.classList.add('visible'); toast('OBJETIVO: LOCALIZA EL REGISTRO DEL LABORATORIO',3.4); subtitle('CONTROL DE CUARENTENA: RESPUESTA NO DISPONIBLE',3.4); last=performance.now(); }
  $('start').addEventListener('click',beginIntro); $('skip-intro').addEventListener('click',beginPlay); $('replay').addEventListener('click',beginIntro);
  $('sound-toggle').addEventListener('click',()=>{muted=!muted;$('sound-toggle').textContent=muted?'◖))':'◖♪'; if(!muted)playSound(440,.1);});
  window.addEventListener('keydown',e=>{ if(['ArrowLeft','ArrowRight','ArrowUp',' ','ArrowDown'].includes(e.key)) e.preventDefault(); keys[e.key.toLowerCase()]=true; if(e.key===' '&&scene==='menu')beginIntro(); if(e.key==='Escape'&&scene==='intro')beginPlay(); });
  window.addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false;});
  document.querySelectorAll('[data-control]').forEach(btn=>{ const c=btn.dataset.control; const down=e=>{e.preventDefault();touch[c]=true;btn.classList.add('pressed'); if(c==='attack')attack(); if(c==='jump')jump(); if(c==='interact')interact();}; const up=e=>{e.preventDefault();touch[c]=false;btn.classList.remove('pressed');}; btn.addEventListener('pointerdown',down); ['pointerup','pointercancel','pointerleave'].forEach(ev=>btn.addEventListener(ev,up)); });
  function updateHud(){ $('health-fill').style.width=Math.max(0,player.health)+'%'; $('health-value').textContent=Math.ceil(player.health); $('objective').textContent=player.opened?'LLEGA A LA CÁMARA DE ESCAPE':player.sample?'REACTIVA EL NÚCLEO': 'ENCUENTRA EL REGISTRO X-17'; }
  function jump(){ if(scene==='playing'&&player.grounded){player.vy=-520;player.grounded=false;playSound(145,.09,'triangle',.022);} }
  function attack(){ if(scene!=='playing'||player.attackCooldown>0)return; player.attackCooldown=.48;player.pulse=.28;pulseFlash=.13;playSound(270,.13,'sawtooth',.045); const target=enemies.find(e=>e.hp>0&&Math.abs(e.x-player.x)<195&&Math.sign(e.x-player.x)===player.facing); if(target){target.hp=0;for(let i=0;i<12;i++)particles.push({x:target.x,y:floorY()-20-Math.random()*26,vx:(Math.random()-.5)*140,vy:-Math.random()*180,life:.5+Math.random()*.5,color:'#c85c62'});playSound(75,.2,'square',.04);toast('AMENAZA NEUTRALIZADA',1.3);} }
  function interact(){if(scene!=='playing')return; const item=worldItems.find(i=>i.active&&Math.abs(i.x-player.x)<95);if(!item){toast('NO HAY NADA QUE PUEDAS USAR AQUÍ',1.4);return;} if(item.type==='terminal'){item.active=false;player.sample=true;updateHud();toast('REGISTRO RECUPERADO · EL ORGANISMO REACCIONA AL SONIDO',3.2);subtitle('DRA. SATO: «No es un parásito. Es una colonia. Está intentando volver a casa.»',5);playSound(520,.2,'sine');} else if(item.type==='reactor'){if(!player.sample){toast('ACCESO DENEGADO · RECUPERA ANTES EL REGISTRO X-17',2);return;}item.active=false;player.opened=true;updateHud();toast('NÚCLEO ESTABLE · CÁMARA DE ESCAPE DESBLOQUEADA',3.2);subtitle('VEGA: «Si el núcleo vuelve a emitir, la colonia sabrá dónde estamos.»',4);playSound(610,.4,'triangle');}else if(item.type==='med'){item.active=false;player.health=Math.min(100,player.health+35);updateHud();toast('BOTIQUÍN USADO · INTEGRIDAD RESTAURADA',1.8);playSound(390,.1,'sine');}else if(item.type==='exit'){if(!player.opened){toast('COMPUERTA BLOQUEADA · RESTAURA EL NÚCLEO',1.8);return;}finish(true);}}
  function floorY(){return Math.round(H*floorRatio);}
  function finish(win){scene='end';gameUI.classList.remove('visible');show(endScreen);$('end-title').textContent=win?'UNA SEÑAL EN LA OSCURIDAD':'LA ESTACIÓN TE RECLAMA';$('end-copy').textContent=win?'Escapaste con el registro de la colonia. A lo lejos, una segunda señal responde desde la superficie de Ío. La cuarentena apenas comienza.':'La colonia ya conoce tu pulso. La próxima vez, no dejes que se acerque.';playSound(win?440:65,.8,win?'sine':'sawtooth',.055);}

