function finish(win){scene='end';gameUI.classList.remove('visible');show(endScreen);$('end-title').textContent=win?'UNA SEÑAL EN LA OSCURIDAD':'LA ESTACIÓN TE RECLAMA';$('end-copy').textContent=win?'Escapaste con el registro de la colonia. A lo lejos, una segunda señal responde desde la superficie de Ío. La cuarentena apenas comienza.':'La colonia ya conoce tu pulso. La próxima vez, no dejes que se acerque.';playSound(win?440:65,.8,win?'sine':'sawtooth',.055);}
function rect(x,y,w,h,color){ctx.fillStyle=color;ctx.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h));}
function line(x1,y1,x2,y2,color,width=1){ctx.strokeStyle=color;ctx.lineWidth=width;ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.stroke();}
function drawBackground(){
  const grad=ctx.createLinearGradient(0,0,0,H);grad.addColorStop(0,'#080e17');grad.addColorStop(.52,'#101820');grad.addColorStop(1,'#11191d');ctx.fillStyle=grad;ctx.fillRect(0,0,W,H);
  // Distant planet and scattered stars beyond the observation ports.
  for(let i=0;i<80;i++){let x=((i*173.7-camera*.08)% (W+40)+W+40)%(W+40),y=(i*67.3+25)%(H*.52);ctx.globalAlpha=.16+(i%4)*.08;rect(x,y, i%7===0?2:1,1,'#b9dbe3');}ctx.globalAlpha=1;
  const px=W*.78-camera*.018,py=H*.25;ctx.globalAlpha=.45;ctx.fillStyle='#192e43';ctx.beginPath();ctx.arc(px,py,Math.min(W,H)*.1,0,Math.PI*2);ctx.fill();ctx.globalAlpha=.3;ctx.fillStyle='#7b9fa5';ctx.beginPath();ctx.arc(px-12,py-8,Math.min(W,H)*.097,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;
  const f=floorY();
  // Bulkhead silhouettes and luminous portholes.
  for(let i=-1;i<Math.ceil(W/360)+3;i++){let x=i*360-(camera*.27%360);rect(x,100,150,H*.49,'#111c24');rect(x+13,115,124,H*.43,'#17252c');rect(x+26,130,98,Math.max(90,H*.30),'#08151d');ctx.fillStyle='#284552';ctx.globalAlpha=.4;ctx.beginPath();ctx.ellipse(x+75,130+H*.13,48,Math.min(72,H*.11),0,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;line(x+22,115,x+128,115,'#55727a',2);line(x+19,f-11,x+131,f-11,'#40535b',2);}
  // Light shafts / emergency washes.
  const glow=ctx.createRadialGradient(W*.66,H*.58,4,W*.66,H*.58,W*.38);glow.addColorStop(0,'#1f899022');glow.addColorStop(1,'#15232b00');ctx.fillStyle=glow;ctx.fillRect(0,0,W,H);
}
function drawWorld(){
  const f=floorY(), left=camera-40, right=camera+W+40;
  // Room plate panels, cable lines, and wall treatments.
  for(let x=Math.floor(left/160)*160;x<right;x+=160){let sx=x-camera;const room=roomData.find(r=>x>=r.x&&x<r.end)||roomData[0];rect(sx,110,156,f-112,'#111a20');rect(sx+4,114,148,f-118,'#131f25');line(sx+5,118,sx+151,118,'#30424a');line(sx+5,f-38,sx+151,f-38,'#2b3c42');rect(sx+12,137,3,Math.max(28,f*.13),room.color);rect(sx+22,137,36,3,'#33434a');rect(sx+22,145,22,2,'#26383e');if(x%320===0){rect(sx+105,145,32,14,'#18262b');rect(sx+109,149,5,5,'#4ab6bc');rect(sx+118,149,15,2,'#60777c');}}
  // Doors mark room transitions.
  roomData.slice(1).forEach((r,index)=>{let x=r.x-camera;if(x< -100||x>W+100)return;rect(x-34,137,68,f-137,'#080e13');rect(x-27,142,54,f-146,'#25353a');rect(x-22,149,44,f-155,'#0c161b');line(x-36,137,x+36,137,'#718288',2);rect(x-37,f-57,4,36,index===2?'#e6544e':'#55cbd0');rect(x+33,f-57,4,36,'#273b40');rect(x-10,153,20,3,'#69838a');});
  // Continuous industrial floor, seams and wet reflections.
  rect(0,f,W,H-f,'#1c282d');rect(0,f,W,4,'#596970');rect(0,f+4,W,3,'#10171b');
  for(let x=Math.floor(left/120)*120;x<right;x+=120){let sx=x-camera;line(sx,f+10,sx,f+23,'#33444a');line(sx+5,f+H*.1,sx+62,f+H*.1,'#27363b');rect(sx+34,f+H*.055,18,2,'#71868a');}
  // Amber/red emergency lamps and floor pools.
  for(let i=0;i<5;i++){let x=380+i*720-camera;if(x>-20&&x<W+20){ctx.globalAlpha=.13;ctx.fillStyle=i===2?'#f04a3c':'#f3a34c';ctx.beginPath();ctx.ellipse(x,f-3,75,14,0,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;rect(x-3,127,7,5,i===2?'#f05a50':'#dfaa65');}}
  drawProps(f); drawEnemies(f); drawPlayer(f); drawFX(); drawPrompt(f);
}
function drawProps(f){
  for(const item of worldItems){if(!item.active)continue;const x=item.x-camera;if(x< -100||x>W+100)continue;
    if(item.type==='terminal'){rect(x-29,f-68,58,68,'#24363b');rect(x-24,f-63,48,42,'#0b1c21');rect(x-19,f-58,38,31,'#14383a');rect(x-14,f-52,16,2,'#70e1d8');rect(x-14,f-46,27,2,'#458d92');rect(x-14,f-40,22,2,'#458d92');rect(x-5,f-20,10,15,'#35484c');rect(x-26,f-5,52,5,'#718187');ctx.globalAlpha=.4;ctx.fillStyle='#4ee1dc';ctx.beginPath();ctx.ellipse(x,f-44,32,26,0,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;}
    if(item.type==='reactor'){rect(x-36,f-114,72,114,'#26343a');rect(x-29,f-106,58,99,'#101b21');ctx.fillStyle='#44d4cf';ctx.globalAlpha=.75+Math.sin(time*5)*.2;ctx.beginPath();ctx.arc(x,f-60,18,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;ctx.strokeStyle='#a1faf0';ctx.lineWidth=2;ctx.beginPath();ctx.arc(x,f-60,27,0,Math.PI*2);ctx.stroke();rect(x-9,f-113,18,7,'#eb6958');rect(x-28,f-19,7,13,'#73868a');rect(x+21,f-19,7,13,'#73868a');}
    if(item.type==='exit'){rect(x-58,f-154,116,154,'#213139');rect(x-49,f-146,98,146,'#0b151b');rect(x-42,f-136,84,136,'#152329');line(x,f-133,x,f-8,'#465b60',2);rect(x-54,f-153,108,5,'#b8c5c1');rect(x-54,f-70,5,23,player.opened?'#65e4d6':'#e65551');rect(x+49,f-70,5,23,player.opened?'#65e4d6':'#e65551');if(player.opened){ctx.globalAlpha=.25;ctx.fillStyle='#87fff0';ctx.fillRect(x-48,f-140,96,135);ctx.globalAlpha=1;}}
    if(item.type==='med'){rect(x-15,f-27,30,27,'#27353a');rect(x-11,f-24,22,17,'#172326');rect(x-6,f-20,12,9,'#d7e5df');rect(x-2,f-18,4,5,'#d65f5d');rect(x-11,f-5,22,5,'#60777b');}
  }
}

function finish(win){scene='end';gameUI.classList.remove('visible');show(endScreen);$('end-title').textContent=win?'UNA SEÑAL EN LA OSCURIDAD':'LA ESTACIÓN TE RECLAMA';$('end-copy').textContent=win?'Escapaste con el registro de la colonia. A lo lejos, una segunda señal responde desde la superficie de Ío. La cuarentena apenas comienza.':'La colonia ya conoce tu pulso. La próxima vez, no dejes que se acerque.';playSound(win?440:65,.8,win?'sine':'sawtooth',.055);}
