const fs = require('fs');
(async () => {
  const targets = await (await fetch('http://localhost:9222/json/list')).json();
  const target = targets.find((item) => item.type === 'page' && item.url.includes('localhost:3002'));
  const ws = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });
  let id = 0;
  const pending = new Map();
  ws.onmessage = ({ data }) => {
    const message = JSON.parse(data);
    if (pending.has(message.id)) { pending.get(message.id)(message); pending.delete(message.id); }
  };
  const send = (method, params = {}) => new Promise((resolve) => {
    const thisId = ++id;
    pending.set(thisId, resolve);
    ws.send(JSON.stringify({ id: thisId, method, params }));
  });
  const evaluate = async (expression) => (await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true })).result.result.value;
  await send('Emulation.setDeviceMetricsOverride', { width: 390, height: 844, deviceScaleFactor: 1, mobile: true });
  await evaluate("document.getElementById('start').click()");
  await new Promise((resolve) => setTimeout(resolve, 300));
  await send('Page.enable');
  const intro = await send('Page.captureScreenshot', { format: 'png' });
  fs.writeFileSync('/tmp/opencode/ios-intro.png', Buffer.from(intro.result.data, 'base64'));
  const storyState = await evaluate("({scene:document.getElementById('intro').className, story:document.getElementById('story-text').getBoundingClientRect().top, errors:window.__errors||[]})");
  await evaluate("document.getElementById('skip-intro').click()");
  await new Promise((resolve) => setTimeout(resolve, 500));
  const gameState = await evaluate("({ui:document.getElementById('game-ui').className, controls:getComputedStyle(document.querySelector('.touch-controls')).display, objective:document.getElementById('objective').textContent, canvas:[document.getElementById('game').width,document.getElementById('game').height]})");
  const game = await send('Page.captureScreenshot', { format: 'png' });
  fs.writeFileSync('/tmp/opencode/ios-game-mobile.png', Buffer.from(game.result.data, 'base64'));
  console.log(JSON.stringify({ storyState, gameState }));
  ws.close();
})();

