  const evaluate = async (expression) => (await send('Runtime.evaluate', { expression, returnByValue: true })).result.result.value;
  await send('Emulation.setDeviceMetricsOverride', { width: 1280, height: 720, deviceScaleFactor: 1, mobile: false });
  await send('Page.enable'); await send('Page.navigate', { url: 'http://localhost:3002/' });
  await new Promise((resolve) => setTimeout(resolve, 500));
  await evaluate("document.getElementById('start').click(); document.getElementById('skip-intro').click()");
  const key = async (type, key, code) => send('Input.dispatchKeyEvent', { type, key, code });
  await key('keyDown', 'd', 'KeyD');
  for (let i = 0; i < 12; i++) { await key('keyDown', 'f', 'KeyF'); await key('keyUp', 'f', 'KeyF'); await new Promise((resolve) => setTimeout(resolve, 450)); }
  await key('keyUp', 'd', 'KeyD');
  console.log(JSON.stringify(await evaluate("({room:document.getElementById('room-name').textContent, objective:document.getElementById('objective').textContent, gameVisible:document.getElementById('game-ui').classList.contains('visible'), end:document.getElementById('end-screen').classList.contains('visible')})")));
  ws.close();
})();
